import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address attacker, uint256 initialFunding, uint256 withdrawAmount) public {
        // 1. Keep domain wide: require attacker != owner, and amounts non-zero
        vm.assume(attacker != address(this));
        vm.assume(initialFunding > 0);
        vm.assume(withdrawAmount > 0);

        // 2. Fund the contract (using owner, which is this test contract)
        vm.deal(address(this), initialFunding);
        (bool fundOk, ) = address(c).call{value: initialFunding}("");
        require(fundOk, "Funding failed");

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore >= withdrawAmount, "Insufficient balance");

        // 3. Attacker (non-owner) tries to withdraw
        vm.prank(attacker);
        bool success = true;
        try c.withdrawAll(address(attacker)) {
        } catch {
            success = false;
        }

        // 4. Property: For any non-owner caller, withdrawAll must revert.
        //    This is true on the reference C (require(msg.sender==owner)).
        //    The mutant (require(true)) will succeed, causing success==true and violating the property.
        assertTrue(!success);
    }
}

