pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        // Restrict to recipients other than the owner to avoid trivial case where owner==recipient.
        vm.assume(recipient != address(this));

        // Fund the contract with some ETH.
        vm.deal(address(c), 1 ether);

        // Deploy a helper that reverts on receiving ETH, and use it as the recipient.
        // This is needed because a fuzzed address is an EOA whose receive always succeeds.
        Reverter reverter = new Reverter();

        // The owner (this contract) calls withdrawAll with the Reverter as recipient.
        // Because the reference C sends to _recipient, the transfer to Reverter will revert.
        // The mutant M sends to owner, so the transfer to owner (address(this)) would succeed.
        vm.prank(address(this));
        try c.withdrawAll(address(reverter)) {
            // The call did not revert.
        } catch {
            // The call reverted.
        }

        // After the call, the contract balance must be 0 if the transfer succeeded.
        // For the reference C, the transfer to Reverter always reverts, so balance remains 1 ether.
        // For the mutant M, the transfer to owner succeeds, so balance becomes 0.
        // The universal property: a successful (non-reverting) withdrawAll by the owner MUST
        // result in contract balance == 0. The reference C never reverts on a fuzzed EOA recipient
        // (so this property holds vacuously for fuzzed EOAs because the call always succeeds and
        // drains the contract). The mutant breaks this property when the recipient is a contract
        // that reverts on receive, because the mutant's transfer to owner succeeds, making the
        // contract balance 0 despite the recipient being a revert contract. Wait — this property
        // isn't right yet.
        // Let's reframe: For the reference C, a call to withdrawAll by the owner with a Reverter
        // as recipient ALWAYS reverts (so balance remains nonzero). For the mutant, the same call
        // ALWAYS succeeds (since it sends to owner, which accepts ETH) and drains the contract.
        // Universal property: After an owner calls withdrawAll, the contract balance is either 0
        // (if the call succeeded) or nonzero (if it reverted). The reference C obeys this trivially.
        // We need a property that FAILS on the mutant. Actually, the correct property is:
        // "After a NON-REVERTING call to withdrawAll by the owner, the contract balance must be 0."
        // For reference C with a Reverter recipient, the call reverts, so balance remains 1 ether;
        // the property holds (implication with false premise is true). For the mutant, the call
        // succeeds, so balance becomes 0; the property holds as well! So that doesn't distinguish.

        // Better: The recipient's balance after a successful call must increase by the contract's
        // previous balance. Since the helper reverts, we can't test this directly because the call
        // reverts on reference. We need a helper that succeeds but allows us to observe where funds went.
        // Instead, use a helper that accepts ETH and tracks whether it received funds.
        Receiver receiver = new Receiver();
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(address(this));
        c.withdrawAll(address(receiver));
        // In reference C, receiver receives the funds (its received() getter returns true).
        // In mutant M, receiver receives nothing (owner gets funds), so received() is false.
        // Property: After owner calls withdrawAll, the recipient contract's received flag must be true.
        // But reference with a fuzzed EOA recipient would fail? No, transfer to EOA always succeeds,
        // but we need to observe the EOA's balance. Since we can't attach a getter to an EOA, we MUST use a helper.
        // The ADVERSARIAL COUNTERPARTY rule says we must deploy a helper when the difference manifests
        // through an external party's BEHAVIOR (revert, receive, etc.).
        // So we deploy Receiver helper for every fuzzed recipient? But recipient is fuzzed; we can't
        // force the fuzzer to use our helper as the recipient without hardcoding. The rule says:
        // "deploy a minimal helper and pass its address where c expects the counterparty, and STILL fuzz the remaining values".
        // That implies we can choose to replace the recipient parameter with the helper's address and fuzz other things.
        // But the signature must have at least one fuzzed parameter. We can fuzz amount, or we can fuzz the helper's behavior.
        // Let's fuzz the amount instead and use a fixed helper as recipient. That still uses a fuzzed parameter (amount).
    }
}

